// Verifies the fault-outranks-cause fix at the real guard, both directions.
// Case D runs a PRE-FIX COPY of the guard (early-return-on-cause), so the
// probe is proved to discriminate rather than assumed to.
const { spawnSync } = require('child_process');
const path = require('path'), fs = require('fs'), os = require('os');

const GUARD = 'D:/claude-kit/plugins/claude-kit/hooks/memory-frontmatter-guard.js';
const base = fs.mkdtempSync(path.join(os.tmpdir(), 'w6-'));
const root = path.join(base, 'store');
const project = path.join(root, 'projects', 'proj', 'memory');
const repo = path.join(base, 'repo');
for (const d of [path.join(project, 'archive'), repo]) fs.mkdirSync(d, { recursive: true });

// The pre-fix guard: the dispatcher returns the first non-null answer,
// fault or cause alike. Built from the shipped file, on a copy.
const src = fs.readFileSync(GUARD, 'utf8');
const FIXED = `    let cause = null;
    for (const check of checks) {
        const answer = check();
        if (answer === null || answer === undefined) continue;
        if (typeof answer.fault === 'string') return answer;
        if (cause === null) cause = answer;
    }
    return cause;`;
if (src.split(FIXED).length - 1 !== 1) throw new Error('rank block not found verbatim');
const PREFIX_GUARD = path.join(base, 'guard.prefix.js');
fs.writeFileSync(PREFIX_GUARD, src.replace(FIXED, `    for (const check of checks) {
        const answer = check();
        if (answer === null || answer === undefined) continue;
        return answer;
    }
    return null;`), 'utf8');

const triggers33 = Array.from({ length: 33 }, (_, i) => 'cmd:run-' + i).join(', ');
const triggers5 = Array.from({ length: 5 }, (_, i) => 'cmd:run-' + i).join(', ');
const BAD_ANCHOR = 'anchors: ../../outside/x.js@ce013625030ba8dba906f756967f9e9ca394464a';

const rec = (lines) => ['---', ...lines, '---', '', '# A record', ''].join('\n');

function run(guard, content) {
    const file = path.join(project, 'a-record.md');
    return spawnSync(process.execPath, [guard], {
        input: JSON.stringify({ tool_name: 'Write', cwd: repo, tool_input: { file_path: file, content } }),
        encoding: 'utf8',
        env: { ...process.env, KIT_MEMORY_ROOT: root, KIT_MEMORY_ROOT_ALLOW_DATA: '1', KIT_MEMORY_PROJECT: '' },
        timeout: 20000
    });
}

const cases = [
    ['A  cut triggers + bad anchors, FIXED guard', GUARD, rec(['metadata:', '  triggers: ' + triggers33, '  ' + BAD_ANCHOR]), 2],
    ['B  cut triggers alone,        FIXED guard', GUARD, rec(['metadata:', '  triggers: ' + triggers33]), 0],
    ['C  clean triggers + bad anchors, FIXED', GUARD, rec(['metadata:', '  triggers: ' + triggers5, '  ' + BAD_ANCHOR]), 2],
    ['D  cut triggers + bad anchors, PRE-FIX', PREFIX_GUARD, rec(['metadata:', '  triggers: ' + triggers33, '  ' + BAD_ANCHOR]), 0]
];

let bad = 0;
for (const [label, guard, content, want] of cases) {
    const r = run(guard, content);
    const got = r.status;
    const ok = got === want;
    if (!ok) bad++;
    console.log((ok ? 'ok  ' : 'FAIL') + '  ' + label + '  exit ' + got + ' (want ' + want + ')');
    if (r.stderr) console.log('        ' + r.stderr.trim().slice(0, 150));
}
console.log('\nmismatches:', bad);
console.log(bad === 0
    ? 'DISCRIMINATING: A denies where D (pre-fix) allows on identical input.'
    : 'NOT PROVEN');
fs.rmSync(base, { recursive: true, force: true });
EOF
